import React, { useState } from "react";
import Swal from "sweetalert2";
import "bootstrap/dist/css/bootstrap.min.css";
//import Plantilla from './plantilla_carga_tipologias.xlsx';
import config from './config';
import * as XLSX from "xlsx";

const App = () => {
  const [loaderVisible, setLoaderVisible] = useState(false);
  const [file, setFile] = useState(null);
  const valoresArray = ["TIPO_GESTION", "TIPOLOGIA"
    , "SUB_TIPOLOGIA_SIN_PARAMETRO", "RAZON_MORA_SIN_PARAMETRO"
    , "TIPO_CONTACTO_SIN_PARAMETRO"]; // Array con los valores para el parámetro 'ddl'


  const getUrlParams = () => {
    const params = new URLSearchParams(window.location.search);
    const id = params.get("id");
    const campana = params.get("campana");

    if (!id || !campana) {
      throw new Error("Faltan parámetros en la URL.");
    }

    return { id, campana };
  };

  const handleTokenError = () => {
    localStorage.removeItem("token");
    Swal.fire("Error", "No estás autenticado. Por favor, inicia sesión.", "error").then(() => {
      window.location.href = "/";
    });
  };

  const decrypt = async (value) => {
    if (!value || value.trim() === "") {
      throw new Error("El valor encriptado está vacío o es inválido.");
    }

    const token = localStorage.getItem('token');
    if (!token) {
      handleTokenError();
      return;
    }

      const response = await fetch(`${config.API_BASE_URL}/decrypt`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ encrypted_value: value }),
    });

    if (response.status === 401) {
      handleTokenError();
      return;
    }
  
    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Error al desencriptar: ${errorText}`);
    }

    const data = await response.json();
    if (!data.decrypted_value) {
      throw new Error("La API no devolvió un valor desencriptado.");
    }

    return data.decrypted_value;
  };

  const handleFileChange = (event) => {
    setFile(event.target.files[0]);
  };

  const fetchDataForExcel = async () => {
    const token = localStorage.getItem("token");
    if (!token) {
      handleTokenError();
      return;
    }

    const urlParams = getUrlParams();
    const idCampana = await decrypt(urlParams.campana);

    const dataColumns = [];
    try {
      for (const valor of valoresArray) {
        const response = await fetch(`${config.API_BASE_URL}/drops`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            id_campana: idCampana, // Ajusta este valor si es necesario
            ddl: valor,
          }),
        });

        if (!response.ok) {
          throw new Error(`Error al obtener datos para ${valor}: ${response.statusText}`);
        }

        const data = await response.json();
        // Extrae los valores del atributo 'ITEM' y los agrega a una columna
        const columnData = data.map((item) => item.ITEM);
        dataColumns.push(columnData);
      }
    } catch (error) {
      console.error("Error al consumir el API:", error.message);
      Swal.fire("Error", `Error al obtener datos del servidor: ${error.message}`, "error");
    }

    return dataColumns;
  };

  const handleDownloadTemplate = async () => {
    const workbook = XLSX.utils.book_new();
  
    // Crear la hoja principal (Plantilla)
    const worksheet1 = XLSX.utils.aoa_to_sheet([["ID GESTIÓN","TIPO DE GESTIÓN", "TIPOLOGÍA", "SUB-TIPOLOGÍA", "RAZÓN DE MORA", "TIPO DE DESCUENTO", "OBSERVACIONES", "INVESTIGACIÓN", "FECHA", "HORA"]]);
    XLSX.utils.book_append_sheet(workbook, worksheet1, "Plantilla");
  
    // Obtener datos para la segunda hoja
    const dataColumns = await fetchDataForExcel();
  
    if (dataColumns.length > 0) {
      // Crear la segunda hoja con encabezados
      const worksheet2 = {};
      const headers = valoresArray.map((valor, index) => valor.replace("_SIN_PARAMETRO", "")); // Generar encabezados sin "_SIN_PARAMETRO"
      headers.forEach((header, columnIndex) => {
        const headerCellAddress = XLSX.utils.encode_cell({ c: columnIndex, r: 0 });
        worksheet2[headerCellAddress] = { t: "s", v: header };
      });
  
      // Agregar datos debajo de los encabezados
      dataColumns.forEach((columnData, columnIndex) => {
        columnData.forEach((value, rowIndex) => {
          const cellAddress = XLSX.utils.encode_cell({ c: columnIndex, r: rowIndex + 1 }); // +1 para dejar espacio al encabezado
          worksheet2[cellAddress] = { t: "s", v: value };
        });
      });
  
      worksheet2["!ref"] = XLSX.utils.encode_range({
        s: { c: 0, r: 0 },
        e: { c: dataColumns.length - 1, r: dataColumns[0].length },
      });
  
      XLSX.utils.book_append_sheet(workbook, worksheet2, "Datos Adicionales");
    }
  
    // Generar el archivo Excel
    const excelData = XLSX.write(workbook, { bookType: "xlsx", type: "array" });
    const blob = new Blob([excelData], { type: "application/octet-stream" });
  
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "plantilla_carga_tipologias.xlsx";
    link.click();
  };
  
  const renderErrorTable = (errores) => {
    const errorTable = document.createElement("table");
    errorTable.classList.add("table", "table-bordered", "mt-3");

    const headerRow = errorTable.insertRow();
    const headers = ["Fila", "Mensaje de Error"];
    headers.forEach((headerText) => {
      const th = document.createElement("th");
      th.textContent = headerText;
      headerRow.appendChild(th);
    });

    errores.forEach((error) => {
      const row = errorTable.insertRow();
      const cellFila = row.insertCell(0);
      const cellMensaje = row.insertCell(1);

      cellFila.textContent = error.fila;
      cellMensaje.textContent = error.mensaje;
    });

    const container = document.querySelector(".card-body");
    const existingTable = container.querySelector("table");
    if (existingTable) {
      existingTable.remove();
    }
    container.appendChild(errorTable);
  };

  const downloadErrorReport = (errores) => {
    const worksheet = XLSX.utils.json_to_sheet(errores);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Errores");

    const excelData = XLSX.write(workbook, { bookType: "xlsx", type: "array" });

    const blob = new Blob([excelData], { type: "application/octet-stream" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "reporte_errores_tipologias.xlsx";
    link.click();
  };

  const convertTo24HourFormat = (time) => {
    if (!time) {
      throw new Error("El valor de hora está vacío o es inválido.");
    }
  
    // Detectar si el valor es un número decimal
    if (!isNaN(time)) {
      const totalSeconds = parseFloat(time) * 24 * 60 * 60; // Convertir días fraccionados a segundos
      const hours = Math.floor(totalSeconds / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = Math.floor(totalSeconds % 60);
  
      return `${hours.toString().padStart(2, "0")}:${minutes
        .toString()
        .padStart(2, "0")}:${seconds.toString().padStart(2, "0")}`; // Retornar formato HH:mm:ss
    }
  
    // Manejar formato tradicional hh:mm:ss a. m./p. m.
    const match = time
      .toUpperCase()
      .replace("P. M.", "PM")
      .replace("A. M.", "AM")
      .match(/(\d+):(\d+):(\d+)\s?(AM|PM)/);
  
    if (!match) {
      throw new Error(`Formato de hora inválido: "${time}". Se esperaba el formato hh:mm:ss a. m./p. m.`);
    }
  
    const [hour, minute, second, meridian] = match.slice(1);
    let hour24 = parseInt(hour, 10);
  
    if (meridian === "PM" && hour24 !== 12) {
      hour24 += 12; // Convertir a formato 24 horas para PM
    } else if (meridian === "AM" && hour24 === 12) {
      hour24 = 0; // Convertir medianoche a 00:00
    }
  
    return `${hour24.toString().padStart(2, "0")}:${minute}:${second}`; // Retornar formato HH:mm:ss
  };
  
  // Función para convertir fecha al formato ISO
  const convertToISODate = (date) => {
    const [day, month, year] = date.split("/").map((part) => part.trim());
    return `${year}-${month}-${day}`; // Formato YYYY-MM-DD
  };

  const convertExcelDateToISO = (excelDate) => {
    if (!isNaN(excelDate)) {
      // Convertir número de días desde 1900-01-01 a una fecha en formato ISO
      const date = new Date((excelDate - 25569) * 86400 * 1000); // 25569 es el offset para 1970-01-01
      return date.toISOString().split("T")[0]; // Retorna sólo la fecha en formato YYYY-MM-DD
    }
    throw new Error(`Formato de fecha inválido: "${excelDate}"`);
  };

  
  const combineDateTime = (date, time) => {
    const formattedDate = !isNaN(date) ? convertExcelDateToISO(date) : convertToISODate(date);
    const formattedTime = !isNaN(time) ? convertTo24HourFormat(time) : convertTo24HourFormat(time);
  
    try {
      // Crear un objeto de fecha y hora combinado
      const dateTime = new Date(`${formattedDate}T${formattedTime}`);
      
      // Restar 6 horas
      dateTime.setHours(dateTime.getHours() - 6);
      
      // Devolver el resultado en formato ISO
      return dateTime.toISOString();
    } catch (error) {
      throw new Error(`Error al combinar fecha y hora: Fecha (${date}), Hora (${time}).`);
    }
  };
  

  const handleUploadFile = async () => {
    if (!file) {
      return Swal.fire("Error", "Debe seleccionar un archivo.", "error");
    }
  
    if (!file.name.endsWith(".xlsx")) {
      return Swal.fire("Error", "El archivo debe ser un archivo Excel (.xlsx).", "error");
    }
  
    setLoaderVisible(true);
  
    try {
      const token = localStorage.getItem("token");
      if (!token) {
        handleTokenError();
        return;
      }
  
      const urlParams = getUrlParams();
      //const idCampana = await decrypt(urlParams.campana);
      const usuarioOperacion = await decrypt(urlParams.id);
  
      const reader = new FileReader();
      reader.onload = async (event) => {
        const data = new Uint8Array(event.target.result);
        const workbook = XLSX.read(data, { type: "array" });
        const sheetName = workbook.SheetNames[0];
        const rows = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName], { header: 1 });
  
        if (!rows || rows.length <= 1) {
          setLoaderVisible(false);
          return Swal.fire("Error", "El archivo Excel no contiene filas de datos.", "error");
        }
  
        // Filtrar filas válidas
        const dataRows = rows.slice(1).filter((row) =>
          row.some((cell) => cell !== null && cell !== undefined && cell.toString().trim() !== "")
        );
  
        if (dataRows.length === 0) {
          setLoaderVisible(false);
          return Swal.fire("Error", "El archivo Excel no contiene datos válidos.", "error");
        }
  
        const errores = [];
  
        // Procesar cada fila del archivo Excel
        for (let index = 0; index < dataRows.length; index++) {
          const row = dataRows[index];
          try {
            /*const fecha = row[8]?.toString().trim() || ""; // Columna de FECHA
            const hora = row[9]?.toString().trim() || ""; // Columna de HORA*/
            const fecha = row[8]; // Columna de FECHA
            const hora = row[9]; // Columna de HORA
            const fechaCreacion = combineDateTime(fecha, hora); // Combinar fecha y hora
  
            // Crear el cuerpo del request
            const body = {
              p_id_gestion: parseInt(row[0], 10) || null,
              p_tipogestion: row[1]?.toString() || "",
              p_tipologia: row[2]?.toString() || "",
              p_sub_tipologia: row[3]?.toString() || "",
              p_razon_mora: row[4]?.toString() || "",
              p_tipo_contacto: row[5]?.toString() || "",
              p_observaciones: row[6]?.toString() || "",
              p_investigacion: row[7]?.toString() || "",
              p_fecha_creacion: fechaCreacion,
              p_id_usuario: parseInt(usuarioOperacion, 10) || null,
            };
  
            // Consumir la API
            const response = await fetch(`${config.API_BASE_URL}/carga-tipologia-gestiones`, {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${token}`,
              },
              body: JSON.stringify(body),
            });
  
            if (!response.ok) {
              throw new Error(`Error en la fila ${index + 2}: ${response.statusText}`);
            }
          } catch (e) {
            errores.push({ fila: index + 2, mensaje: e.message });
          }
        }
  
        setLoaderVisible(false);
  
        // Manejo de errores
        if (errores.length > 0) {
          renderErrorTable(errores);
          downloadErrorReport(errores);
          Swal.fire(
            "Atención",
            "Algunas filas tienen errores. Por favor, verifica el reporte de errores.",
            "warning"
          );
        } else {
                            Swal.fire("Éxito", "Archivo procesado correctamente.", "success").then(() => {
                              // Redirigir a la pestaña deseada
                              const urlParams = getUrlParams();
                              window.location.href = `./carga_tipologias?id=${urlParams.id}&campana=${urlParams.campana}`;
                            });
        }
      };
  
      reader.readAsArrayBuffer(file);
    } catch (error) {
      setLoaderVisible(false);
      Swal.fire("Error", error.message, "error");
    }
  };
  

  const handleBackToPanel = () => {
    const urlParams = getUrlParams();
    window.location.href = `./modulos?id=${urlParams.id}&campana=${urlParams.campana}`;
  };

  return (
    <div className="container mt-5">
      <div className="card">
        <div className="card-header text-center">
          <h4>Carga de Gestiones</h4>
          <button className="btn btn-warning" onClick={handleBackToPanel}>
            Regresar al panel de módulos
          </button>
        </div>
        <div className="card-body">
          <div className="mb-3">
            <button className="btn btn-primary" onClick={handleDownloadTemplate}>
              Descargar Plantilla
            </button>
          </div>
          <form>
            <div className="mb-3">
              <label htmlFor="fileInput" className="form-label">
                Subir archivo Excel
              </label>
              <input type="file" className="form-control" id="fileInput" accept=".xlsx" onChange={handleFileChange} />
            </div>
            <button type="button" className="btn btn-success" onClick={handleUploadFile}>
              Cargar
            </button>
          </form>
          {loaderVisible && <div className="loader mt-3"></div>}
        </div>
      </div>
    </div>
  );
};

export default App;
